{"packet_id":"D053-01","doc_id":"D053","jurisdiction":"MA","category":"just_cause_eviction","lifecycle":"enacted","title":"Massachusetts anti-reprisal protection against retaliatory termination","requirement":"A landlord may not threaten or take reprisal against a tenant for reporting housing or health code violations, enforcing housing laws, or organizing or joining a tenants' union. A notice of termination within six months of that activity is presumed retaliatory.","key_value":"6 months","coverage_conditions":"All tenants of residential premises in Massachusetts who report violations, bring or obtain relief in enforcement actions, or organize or join a tenants' union.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"A notice of termination for nonpayment of rent is outside the rebuttable presumption.","penalty":"Damages of not less than one month's rent nor more than three months' rent, or actual damages if greater, plus costs and a reasonable attorney's fee.","effective_date":null,"citation":"G.L. c. 186, § 18","quoted_span":"The receipt of any notice of termination of tenancy, except for nonpayment of rent, or, of increase in rent, or, of any substantial alteration in the terms of tenancy within six months after the tenant has commenced, proceeded with, or obtained relief in such action,","interaction":null,"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D053-01","doc_id":"D053","jurisdiction":"MA","category":"rent_increase_limits","lifecycle":"enacted","title":"Massachusetts anti-reprisal presumption for rent increases","requirement":"A landlord's notice of a rent increase within six months after a tenant reports violations, enforces housing laws, or organizes a tenants' union is presumed to be a reprisal, rebuttable only by clear and convincing evidence of independent justification.","key_value":"6 months","coverage_conditions":"Tenants of residential premises in Massachusetts who report violations, enforce housing laws, or engage in tenants' union activity.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":"Damages of not less than one month's rent nor more than three months' rent, or actual damages if greater, plus costs and a reasonable attorney's fee.","effective_date":null,"citation":"G.L. c. 186, § 18","quoted_span":"or, of increase in rent, or, of any substantial alteration in the terms of tenancy within six months after the tenant has commenced, proceeded with, or obtained relief in such action, exercised such rights, made such report or complaint, or organized or joined such tenants' union","interaction":null,"confidence":0.9,"conflict_flag":false,"conflict_note":null}
